/* -------------------------------------------------------
   SINGLE PANEL
------------------------------------------------------- */

function StoryPanel({
  panel,
  index,
  progress,
  reducedMotion,
}) {
  const total = panels.length;

  /*
    Each panel owns one portion of the scroll.

    Example with 5 panels:

    0.00 ───── 0.20  PANEL 01
    0.20 ───── 0.40  PANEL 02
    0.40 ───── 0.60  PANEL 03
    0.60 ───── 0.80  PANEL 04
    0.80 ───── 1.00  PANEL 05
  */

  const start = index / total;
  const end = (index + 1) / total;

  const enter = start;
  const center = start + (end - start) * 0.42;
  const leave = end;

  /*
    Image + text fade/scale.
  */

  const opacityValues = index === 0
    ? [1, 1, 0]
    : index === total - 1
      ? [0, 1, 1]
      : [0, 1, 0];
  const opacity = useTransform(
    progress,
    [enter, center, leave],
    opacityValues,
  );

  const scale = reducedMotion
    ? 1
    : useTransform(
        progress,
        [enter, center, leave],
        [0.94, 1, 1.04]
      );

  /*
    Alternate direction.

    Even:
      IMAGE LEFT
      INFO RIGHT

    Odd:
      INFO LEFT
      IMAGE RIGHT
  */

  const imageIsLeft = index % 2 === 0;

  const imageX = reducedMotion
    ? 0
    : useTransform(
        progress,
        [enter, center, leave],
        imageIsLeft
          ? ['-7vw', '0vw', '-4vw']
          : ['7vw', '0vw', '4vw']
      );

  const infoX = reducedMotion
    ? 0
    : useTransform(
        progress,
        [enter, center, leave],
        imageIsLeft
          ? ['7vw', '0vw', '4vw']
          : ['-7vw', '0vw', '-4vw']
      );

  const imageScale = reducedMotion
    ? 1
    : useTransform(
        progress,
        [enter, center, leave],
        [0.9, 1, 1.06]
      );

  const markerScale = reducedMotion
    ? 1
    : useTransform(
        progress,
        [enter, center, leave],
        [0.5, 1, 1.15]
      );

  return (
    <motion.article
      className="scroll-story-panel"
      style={{
        opacity,
        scale,
        zIndex: index + 1,
      }}
      aria-label={`${panel.number} ${panel.eyebrow}`}
    >
      {/* ------------------------------------------------
          IMAGE
      ------------------------------------------------ */}

      <motion.div
        className={`scroll-story-image ${
          imageIsLeft
            ? 'scroll-story-image--left'
            : 'scroll-story-image--right'
        }`}
        style={{
          x: imageX,
          scale: imageScale,
        }}
      >
        <div className="scroll-story-image__frame">
          <Image
            src={panel.image}
            alt={panel.imageAlt}
            fill
            priority={index < 2}
            sizes="(max-width: 768px) 100vw, 50vw"
            quality={90}
            className="scroll-story-image__img"
          />

          <div
            className="scroll-story-image__grid"
            aria-hidden="true"
          />

          {/* orange technical line */}

          <span
            className="scroll-story-line"
            aria-hidden="true"
          />

          {/* orange marker */}

          <motion.span
            className="scroll-story-marker"
            style={{
              scale: markerScale,
            }}
            aria-hidden="true"
          >
            {panel.marker}
          </motion.span>

          {/* little white close box */}

          <span
            className="scroll-story-close"
            aria-hidden="true"
          >
            ×
          </span>

          <span
            className="scroll-story-code"
            aria-hidden="true"
          >
            {panel.code}
          </span>
        </div>
      </motion.div>

      {/* ------------------------------------------------
          INFORMATION STRIP
      ------------------------------------------------ */}

      <motion.div
        className={`scroll-story-info ${
          imageIsLeft
            ? 'scroll-story-info--right'
            : 'scroll-story-info--left'
        }`}
        style={{
          x: infoX,
        }}
      >
        <div className="scroll-story-info__inner">
          <div className="scroll-story-info__number">
            <span>{panel.number}</span>
            <span className="scroll-story-info__slash">
              /
            </span>
            <span>
              {String(total).padStart(2, '0')}
            </span>
          </div>

          <p className="scroll-story-info__eyebrow">
            {panel.eyebrow}
          </p>

          <h2>{panel.title}</h2>

          <p className="scroll-story-info__description">
            {panel.description}
          </p>

          <div className="scroll-story-info__bottom">
            <span>PALMO COCONUT CO.</span>

            <span className="scroll-story-info__orange-dot" />
          </div>
        </div>
      </motion.div>
    </motion.article>
  );
}

/* -------------------------------------------------------
   MAIN SECTION
------------------------------------------------------- */

export default function ScrollStory() {
  const sectionRef = useRef(null);
  const reducedMotion = useReducedMotion();

  const { scrollYProgress } = useScroll({
    target: sectionRef,
    offset: ['start start', 'end end'],
  });
  const storyProgress = useTransform(
    scrollYProgress,
    (value) => Math.max(0, Math.min(1, value)),
  );

  return (
    <section
      ref={sectionRef}
      className="scroll-story"
      id="story"
      aria-label="Our story"
    >
      <div className="scroll-story__sticky">

        {/* ---------------------------------------------
            BACKGROUND
        --------------------------------------------- */}

        <div
          className="scroll-story__background"
          aria-hidden="true"
        />

        {/* ---------------------------------------------
            TOP UI
        --------------------------------------------- */}

        <div className="scroll-story__top">
          <span>WHY PALMO</span>

          <span>
            SCROLL TO EXPLORE
          </span>
        </div>

        {/* ---------------------------------------------
            PANELS
        --------------------------------------------- */}

        <div className="scroll-story__viewport">
          {panels.map((panel, index) => (
            <StoryPanel
              key={panel.number}
              panel={panel}
              index={index}
              progress={storyProgress}
              reducedMotion={reducedMotion}
            />
          ))}
        </div>

        {/* ---------------------------------------------
            SIDE PROGRESS
        --------------------------------------------- */}

        <div
          className="scroll-story__progress"
          aria-hidden="true"
        >
          {panels.map((panel, index) => {
            const start = index / panels.length;
            const end = (index + 1) / panels.length;

            const opacity = useTransform(
              storyProgress,
              [start, (start + end) / 2, end],
              [0.25, 1, 0.25]
            );

            return (
              <motion.span
                key={panel.number}
                style={{ opacity }}
              >
                {panel.number}
              </motion.span>
            );
          })}
        </div>

        {/* ---------------------------------------------
            BOTTOM UI
        --------------------------------------------- */}

        <div className="scroll-story__bottom">
          <span>
            GOOD THINGS GROW UNDER THE SUN.
          </span>

          <span>
            PALMO — 2026
          </span>
        </div>
      </div>
    </section>
  );
}